'use strict';
const $ = (s, r=document) => r.querySelector(s);
const $$ = (s, r=document) => [...r.querySelectorAll(s)];
const home = $('#homeView'), page = $('#pageView'), nav = $('#mainNav'), notice = $('#notice');
const menuToggle = $('#menuToggle');
let noticeTimer;
let currentSession=null, sessionChecked=false;
const API_BASE=($('#apiBaseConfig')?.content||document.querySelector('meta[name="qayyum-api-base"]')?.content||'').trim().replace(/\/$/,'');
function apiToken(){try{return localStorage.getItem('qayyum-session-token')||sessionStorage.getItem('qayyum-session-token')||''}catch{return ''}}
function storeSessionToken(token,remember=true){try{localStorage.removeItem('qayyum-session-token');sessionStorage.removeItem('qayyum-session-token');(remember?localStorage:sessionStorage).setItem('qayyum-session-token',token)}catch(err){try{sessionStorage.setItem('qayyum-session-token',token)}catch{throw new Error('تعذر حفظ جلسة الدخول في هذا المتصفح؛ تحقق من إعدادات التخزين.')}}}
function clearSessionToken(){try{localStorage.removeItem('qayyum-session-token');sessionStorage.removeItem('qayyum-session-token')}catch{}}
async function apiRequest(path,options={}){if(!API_BASE)throw new Error('API غير مضبوط؛ أضف عنوان الخادم في meta[name=\"qayyum-api-base\"].');const headers=new Headers(options.headers||{});const token=apiToken();if(token)headers.set('Authorization',`Bearer ${token}`);if(options.body&&!(options.body instanceof FormData))headers.set('Content-Type','application/json');let response;try{response=await fetch(`${API_BASE}${path}`,{...options,headers})}catch{throw new Error('تعذر الاتصال بخادم مكتبة القيّوم. تحقق من اتصال الإنترنت ثم حاول مجدداً.')}if(response.status===401&&token&&!path.startsWith('/api/auth/')){clearSessionToken();currentSession=null;sessionChecked=true;applyRoleNavigation();throw new Error('انتهت صلاحية جلسة الدخول؛ سجّل الدخول من جديد ثم أعد المحاولة.')}const data=response.status===204?null:await response.json().catch(()=>({}));if(!response.ok){const messages={account_exists:'هذا البريد الإلكتروني مسجّل مسبقاً. جرّب تسجيل الدخول بدلاً من إنشاء حساب جديد.',registration_rate_limited:'وصلت إلى الحد المؤقت لمحاولات التسجيل. انتظر قليلاً ثم حاول مجدداً.',invalid_credentials:'البريد الإلكتروني أو كلمة المرور غير صحيحة.',too_many_auth_attempts:'تجاوزت عدد محاولات الدخول المسموح بها مؤقتاً. حاول بعد 15 دقيقة.',database_unreachable:'قاعدة البيانات غير متاحة حالياً. حاول بعد قليل.',google_sign_in_not_configured:'تسجيل Google غير مكتمل الإعداد حالياً.',password_too_long_in_bytes:'كلمة المرور طويلة جداً. استخدم كلمة مرور أقصر.'};const detail=Array.isArray(data?.details)?data.details.map(x=>`${(x.path||[]).join('.')||'حقل'}: ${x.message}`).join('، '):'';const message=messages[data?.error]||(data?.error==='validation_error'?'تحقق من صحة البيانات المدخلة.':data?.error||`حدث خطأ (${response.status})`);throw new Error([message,detail].filter(Boolean).join(' — '));}return data}

function toast(message){notice.textContent=message;notice.classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>notice.classList.remove('show'),3300)}
function hijriDate(){try{return new Intl.DateTimeFormat('ar-SA-u-ca-islamic-umalqura',{day:'numeric',month:'long',year:'numeric'}).format(new Date())}catch{return 'التاريخ الهجري'}}
function gregDate(){return new Intl.DateTimeFormat('ar',{day:'numeric',month:'long',year:'numeric'}).format(new Date())}
