function stat(label,value,desc,id=''){return `<div class="stat-card" ${id?`id="${id}"`:''}><span>${label}</span><strong>${value}</strong><small>${desc}</small></div>`}
function renderLibrary(defaultCategory=''){return `<div class="page-shell"><section class="paper-card"><h2>التصنيفات العلمية الرئيسية</h2><div class="card-body"><div class="grid-3">${taxonomy.map((t,i)=>`<button class="btn secondary" type="button" data-action="category-select" data-category="${escapeHtml(t)}">${String(i+1).padStart(2,'0')} · ${escapeHtml(t)}</button>`).join('')}</div></div></section>
 <div class="notice-strip warning">الفهرس لا يعرض إلا الكتب المعتمدة فعلياً. إذا لم توجد نتائج، فهذا يعني أن السجلات لم تُدخل أو لم تجتز المراجعة بعد؛ لا نعرض كتباً تجريبية على أنها حقيقية.</div>
 <section class="paper-card"><h2>البحث المتقدم في الكتب</h2><div class="card-body"><form id="catalogForm"><div class="form-row"><div class="field"><label for="bookQuery">عنوان الكتاب أو جزء منه</label><input id="bookQuery" placeholder="اسم الكتاب"></div><div class="field"><label for="catalogAuthor">المؤلف</label><input id="catalogAuthor" placeholder="اسم المؤلف"></div><div class="field"><label for="catalogSchool">المذهب / المدرسة</label><select id="catalogSchool"><option value="">جميع المدارس</option><option value="إمامي">إمامي اثنا عشري</option><option value="سني">سني</option><option value="إباضي">إباضي</option><option value="زيدي">زيدي</option><option value="إسماعيلي">إسماعيلي</option></select></div></div><div class="form-row"><div class="field"><label for="catalogCategory">التخصص أو التصنيف</label><input id="catalogCategory" value="${escapeHtml(defaultCategory)}" placeholder="كل التخصصات" list="catalogCategoryOptions"><datalist id="catalogCategoryOptions">${taxonomy.map(t=>`<option value="${escapeHtml(t)}"></option>`).join('')}</datalist></div><div class="field"><label for="catalogLanguage">لغة الكتاب</label><select id="catalogLanguage"><option value="">كل اللغات</option><option value="ar">العربية</option><option value="fa">الفارسية</option><option value="en">الإنجليزية</option><option value="ur">الأردية</option><option value="tr">التركية</option></select></div><div class="field"><label for="catalogType">نوع المادة</label><select id="catalogType"><option value="">الكل</option><option value="book">كتاب</option><option value="manuscript">مخطوط</option><option value="article">بحث / مقالة</option></select></div></div><div class="toolbar"><button class="btn" type="submit">بحث في الفهرس</button><button class="btn secondary" type="reset">مسح الفلاتر</button><button class="btn ghost" type="button" data-action="external-search">إعداد بحث متعدد المصادر</button></div></form></div></section>
 <section class="paper-card"><h2>النتائج</h2><div class="card-body" id="catalogResults"><div class="empty-state">ابدأ بالبحث لعرض الكتب المعتمدة الموجودة في قاعدة البيانات.</div></div></section>
 <section class="grid-3">${stat('عدد المدارس','حسب السجلات المعتمدة','لا يُستنتج المذهب من اسم المؤلف')}${stat('منع التكرار','مراجعة هوية العمل','مطابقة العنوان والمؤلف وهوية العمل')}${stat('تنزيل الملفات','وفق الحقوق','لا تنزيل دون إذن أو ترخيص واضح')}</section>
 </div>`}
function renderResearch(){return `<div class="page-shell"><div class="notice-strip">مشاريعك البحثية خاصة بحسابك عند تسجيل الدخول، أو تحفظ محلياً على هذا الجهاز عند استخدام المكتبة دون خادم.</div><div class="grid-2"><section class="paper-card"><h2>إنشاء مشروع علمي</h2><div class="card-body"><form id="researchForm"><div class="field"><label>عنوان البحث</label><input id="researchTitle" required minlength="3" maxlength="500" placeholder="عنوان المشروع أو المسألة"></div><div class="field"><label>وصف مختصر</label><textarea id="researchDesc" maxlength="12000" placeholder="موضوع البحث وحدوده"></textarea></div><div class="field"><label>نوع المشروع</label><select id="researchType"><option value="research">بحث علمي</option><option value="study">دراسة ومطالعة</option><option value="text_edition">تحقيق نص</option><option value="evidence_comparison">مقارنة أدلة</option><option value="reading_plan">خطة قراءة</option></select></div><button class="btn" type="submit">حفظ المشروع</button></form></div></section><section class="paper-card"><h2>مشاريعي</h2><div class="card-body" id="researchProjects"><div class="empty-state">جارٍ تحميل المشاريع...</div></div></section></div><section class="paper-card" id="researchDetail" hidden><h2>هيكل البحث ومصادره</h2><div class="card-body" id="researchDetailBody"></div></section><div class="grid-3"><div class="tool-tile"><b>📑 هيكل البحث</b><p>أبواب وفصول ومباحث مع ترتيب قابل للتعديل.</p></div><div class="tool-tile"><b>🔖 إدارة المصادر</b><p>حفظ بيانات المصدر والطبعة والجزء والصفحة.</p></div><div class="tool-tile"><b>🧾 سجل النسخ</b><p>الاحتفاظ بإصدارات البحث ومراجعة التغييرات.</p></div></div></div>`}
function renderHadith(){return `<div class="page-shell"><div class="notice-strip">يعرض هذا القسم السجلات الموجودة فعلياً في قاعدة البيانات فقط. لا تُستنتج صحة الرواية أو ضعفها آلياً، وتبقى أقوال العلماء منسوبة إلى أصحابها ومصادرها.</div><section class="paper-card"><h2>البحث في الروايات</h2><div class="card-body"><form id="hadithForm"><div class="form-row"><div class="field"><label>نص الرواية أو عبارة منها</label><input id="hadithQuery" placeholder="اكتب عبارة من المتن"></div><div class="field"><label>اسم الراوي</label><input id="hadithNarrator" placeholder="اسم الراوي"></div><div class="field"><label>المصدر</label><input id="hadithSource" placeholder="اسم الكتاب أو المصنف"></div></div><button class="btn" type="submit">بحث الروايات</button></form></div></section><section class="paper-card"><h2>نتائج البحث</h2><div class="card-body" id="hadithResults"><div class="empty-state">أدخل عبارة بحث أو اسم راوٍ أو مصدر. يلزم تسجيل الدخول واتصال الخادم.</div></div></section></div>`}
function renderCalendar(){return `<div class="page-shell"><div class="calendar-banner"><div class="calendar-date"><span>التاريخ الهجري · الافتراضي</span><strong>${hijriDate()}</strong><span>يعرض حسب تقويم أم القرى في المتصفح، ويحتاج ضبط المرجعية المعتمدة للتواريخ المحلية</span></div><div class="calendar-date"><span>التاريخ الميلادي</span><strong>${gregDate()}</strong><span>للمقارنة فقط</span></div></div><div class="notice-strip">قد يختلف ثبوت بداية الشهر أو تاريخ المناسبة بين المراجع والبلدان. ستُعرض الاختلافات ومصادر كل تاريخ بوضوح، ولا يُفرض تاريخ واحد على الجميع.</div><div class="grid-2"><section class="paper-card"><h2>تفضيلات التقويم</h2><div class="card-body"><label class="field"><span>طريقة عرض التاريخ</span><select id="calendarMode"><option value="hijri">الهجري أولاً ثم الميلادي</option><option value="gregorian">الميلادي أولاً ثم الهجري</option></select></label><label class="field"><span>مرجع اعتماد التاريخ</span><select id="calendarAuthority"><option value="show_variations">عرض الاختلافات مع المصادر</option><option value="user_authority">إعداد مرجعي يحدده المستخدم</option><option value="umm_al_qura">تقويم أم القرى للعرض التقريبي</option></select></label><button class="btn" data-action="save-calendar">حفظ التفضيلات بالحساب</button></div></section><section class="paper-card"><h2>المناسبات القادمة</h2><div class="card-body"><div id="calendarEventsList" class="empty-state">جارٍ تحميل المناسبات المعتمدة…</div></div></section></div><section class="paper-card"><h2>اقتراح مناسبة للمراجعة العلمية</h2><div class="card-body"><form id="eventForm"><div class="form-row"><div class="field"><label>اسم المناسبة</label><input id="eventTitle" required maxlength="300" placeholder="اسم المناسبة"></div><div class="field"><label>التاريخ الهجري</label><input id="eventHijri" maxlength="80" placeholder="مثال: ١٥ شعبان"></div><div class="field"><label>نوع المناسبة</label><select id="eventKind"><option value="birth">ولادة</option><option value="martyrdom">شهادة / وفاة</option><option value="historical">حدث تاريخي</option><option value="general">مناسبة عامة</option></select></div></div><div class="form-row"><div class="field"><label>التاريخ الميلادي والوقت (اختياري)</label><input id="eventStartsAt" type="datetime-local"></div><div class="field"><label>طريقة حساب التاريخ</label><input id="eventCalendarMethod" maxlength="80" placeholder="مثلاً: وفق مصدر محدد"></div></div><div class="field"><label>المصدر وملاحظة اختلاف التاريخ</label><textarea id="eventDescription" required maxlength="5000" placeholder="اذكر المصدر والطبعة والصفحة، وأي اختلاف في التاريخ"></textarea></div><button class="btn" type="submit">إرسال الاقتراح للمراجعة</button><p class="muted">لا تظهر المناسبة للزوار إلا بعد مراجعة المالك واعتمادها.</p></form></div></section></div>`}

function renderStudy(){return `<div class="page-shell"><div class="notice-strip">الملاحظات والاقتباسات خاصة افتراضياً. في وضع الواجهة الثابتة تُحفظ محلياً على هذا الجهاز؛ بعد إعداد API يمكن مزامنتها بحساب المستخدم.</div><div class="grid-3"><div class="tool-tile"><b>📖 دفتر المطالعة</b><p>تدوين الفوائد ومتابعة آخر موضع قراءة.</p><button class="btn secondary" data-action="open-notes">فتح الدفتر</button></div><div class="tool-tile"><b>🔬 دفتر التحقيق</b><p>مقارنة النسخ وإثبات الفروق ومصادر النصوص.</p><button class="btn secondary" data-action="open-investigation">فتح دفتر التحقيق</button></div><div class="tool-tile"><b>🧷 الاقتباسات والحواشي</b><p>حفظ النص مع الجزء والصفحة والطبعة.</p><button class="btn secondary" data-action="open-citations">إدارة الاقتباسات</button></div><div class="tool-tile"><b>📚 خطة القراءة</b><p>تنظيم الكتب والدروس حسب التخصص.</p><button class="btn secondary" data-action="reading-plan">إنشاء خطة</button></div><div class="tool-tile"><b>🧠 المصطلحات العلمية</b><p>حفظ تعريفاتك ومراجعتها ضمن الملاحظات.</p><button class="btn secondary" data-action="terms">بطاقات المصطلحات</button></div><div class="tool-tile"><b>📝 تصدير البحث</b><p>تجهيز المحتوى لاحقاً بصيغ Word وPDF.</p><button class="btn secondary" data-action="export-info">خيارات التصدير</button></div></div><section class="paper-card" id="studyWorkspace"><h2>دفتر الملاحظات والاقتباسات</h2><div class="card-body"><form id="noteForm"><div class="form-row"><div class="field"><label for="noteKind">نوع السجل</label><select id="noteKind"><option value="note">ملاحظة</option><option value="quote">اقتباس</option><option value="citation">إحالة مصدرية</option><option value="research">مادة بحثية / تحقيق</option></select></div><div class="field"><label for="noteTitle">العنوان</label><input id="noteTitle" required placeholder="عنوان الفائدة أو الاقتباس"></div></div><div class="field"><label for="noteBody">النص أو بيانات الإحالة</label><textarea id="noteBody" required placeholder="النص المنقول أو الملاحظة العلمية"></textarea></div><div class="field"><label for="noteLocator">المصدر والطبعة والجزء والصفحة / الموضع</label><input id="noteLocator" placeholder="اسم الكتاب، الطبعة، ج 1، ص 25"></div><button class="btn" type="submit">حفظ في دفتر هذا الجهاز</button></form><div id="savedNotes" class="notice-strip">لا توجد ملاحظات محفوظة.</div></div></section></div>`}
const levels=[1000,2000,4000,8000,16000,32000,64000,128000,256000,512000];
function renderGroups(){return `<div class="page-shell"><div class="notice-strip">المجموعات والقنوات العلمية تخضع لموافقة المالك قبل النشر. المنشورات الجديدة تمر بالمراجعة، والقنوات لا ينشر فيها إلا المدير أو المشرف المعتمد.</div><div class="grid-3">${stat('المستويات','10','لا توجد مستويات بعد العاشر')}${stat('اعتماد الترقية','يدوي','لا يُمنح الوسام تلقائياً')}${stat('مراجعة المالك','إلزامية','إنشاء المجموعات والقنوات')}</div><section class="paper-card"><h2>إنشاء مجموعة أو قناة علمية</h2><div class="card-body"><form id="communitySpaceForm"><div class="form-row"><div class="field"><label>النوع</label><select id="communityKind"><option value="group">مجموعة نقاش علمي</option><option value="channel">قناة نشر علمي</option></select></div><div class="field"><label>اسم المجموعة أو القناة</label><input id="communityName" required minlength="3" maxlength="240"></div><div class="field"><label>الخصوصية</label><select id="communityPrivacy"><option value="public">عامة</option><option value="private">خاصة بطلب انضمام</option></select></div></div><div class="field"><label>الوصف والأهداف العلمية</label><textarea id="communityDescription" maxlength="4000" required></textarea></div><button class="btn" type="submit">إرسال طلب الإنشاء للمالك</button></form></div></section><section class="paper-card"><h2>المجموعات والقنوات المنشورة</h2><div class="card-body"><div class="toolbar"><input id="communitySearch" placeholder="ابحث عن مجموعة أو قناة"><button class="btn secondary" data-action="community-load">بحث وتحديث</button></div><div id="communitySpacesList" class="empty-state">سجّل الدخول لعرض المساحات المعتمدة.</div><div id="communityFeed"></div></div></section><section class="paper-card"><h2>سلم مستويات المجموعات والقنوات</h2><div class="card-body"><div class="level-list">${levels.map((p,i)=>`<div class="level"><span>المستوى ${i+1}</span><b>${p.toLocaleString('en-US')}</b><small>نقطة للترقية</small><div class="progress"><i></i></div><small>${['وسام البداية','وسام النشاط','وسام التفاعل','وسام التميز','وسام النخبة','وسام الريادة','وسام الاحتراف','وسام الإبداع','وسام السيادة','وسام القيّوم'][i]}</small></div>`).join('')}</div><p class="muted">الأوزان: 40% البحوث والمحتوى العلمي، 30% الفعاليات والمبادرات، 20% التفاعل الحقيقي، 10% نمو الأعضاء. اعتماد النقاط والترقيات يبقى خاضعاً للمراجعة.</p></div></section>${currentSession?.accountType==='owner'?`<section class="paper-card"><h2>طلبات إنشاء المجموعات والقنوات · مركز المالك</h2><div class="card-body"><button class="btn secondary" data-action="community-owner-queue">تحميل الطلبات المعلقة</button><div id="communityOwnerQueue"></div></div></section>`:''}</div>`}
function renderAssistant(){return `<div class="page-shell"><div class="notice-strip warning">المساعد العلمي غير متصل حالياً بنموذج ذكاء اصطناعي. لن نعرض إجابات أو مراجع مختلقة؛ يمكنك حفظ السؤال كمسودة في دفتر البحوث.</div><section class="paper-card"><h2>إعداد نطاق المصادر</h2><div class="card-body"><form id="assistantForm"><div class="field"><label for="assistantScope">مصادر الإجابة المطلوبة</label><select id="assistantScope" required><option value="">اختر نطاق المصادر</option><option value="library">مصادر مكتبة القيّوم الموثقة فقط</option><option value="external">مصادر المكتبة والمصادر الخارجية مع تمييزها</option></select></div><div class="field"><label for="assistantQuestion">سؤالك العلمي</label><textarea id="assistantQuestion" required placeholder="اكتب المسألة أو السؤال العلمي"></textarea></div><button class="btn" type="submit">حفظ السؤال كمسودة</button></form><p id="assistantDraftStatus" class="muted" aria-live="polite">سيُحفظ السؤال فقط، ولن يُنشأ جواب آلي قبل تفعيل خدمة المساعد.</p></div></section><div class="grid-3"><div class="tool-tile"><b>📚 توثيق المصادر</b><p>اسم المصدر والطبعة والجزء والصفحة.</p></div><div class="tool-tile"><b>⚖️ فصل المنقول عن التحليل</b><p>تمييز النص الأصلي عن الشرح والاستنتاج.</p></div><div class="tool-tile"><b>🔍 درجة التحقق</b><p>بيان ما ثبت وما يحتاج مراجعة علمية.</p></div></div></div>`}
function renderReader(){return `<div class="page-shell"><div class="notice-strip">قارئ مكتبة القيّوم: تُعرض النسخ المعتمدة داخل الموقع بهوية المكتبة، ولا يُحوَّل القارئ إلى مواقع خارجية.</div><section class="paper-card"><h2>فتح كتاب من مكتبة القيّوم</h2><div class="card-body"><div class="field"><label for="readerLibraryUrl">رابط ملف الكتاب المستضاف ضمن القيّوم</label><input id="readerLibraryUrl" type="url" placeholder="/library-files/book.pdf أو رابط خادم القيّوم"></div><div class="toolbar"><button class="btn" type="button" data-action="reader-open-url">فتح داخل القيّوم</button><span class="muted">يُقبل رابط من نفس الموقع أو من خادم القيّوم المضبوط فقط.</span></div><hr><div class="field"><label for="readerFile">أو افتح ملفاً من جهازك للتجربة</label><input id="readerFile" type="file" accept="application/pdf,.pdf,application/epub+zip,.epub"></div><p class="muted">الملف المحلي لا يُرفع تلقائياً.</p><div class="toolbar"><button class="btn secondary" data-action="reader-prev">السابق</button><button class="btn secondary" data-action="reader-next">التالي</button><button class="btn secondary" data-action="reader-zoom-in">تكبير +</button><button class="btn secondary" data-action="reader-zoom-out">تصغير −</button><button class="btn secondary" data-action="reader-night">الوضع الليلي</button><button class="btn secondary" data-action="reader-bookmark">إضافة علامة</button><button class="btn secondary" data-action="reader-note">ملاحظة على الموضع</button></div><div class="field" style="max-width:220px;margin-top:12px"><label>رقم الصفحة</label><input type="number" min="1" value="1" id="readerPage"></div><div id="readerStatus" class="muted" aria-live="polite">لم يتم فتح كتاب بعد.</div><button class="btn" type="button" data-action="reader-upload">إرسال نسخة إلى حجر المراجعة (يتطلب الدخول)</button></div></section><div class="paper-card" id="readerCanvas"><h2>قارئ مكتبة القيّوم</h2><div class="card-body" id="readerContent"><div class="empty-state">اختر كتاباً معتمداً لقراءته هنا داخل المكتبة.</div></div></div><section class="paper-card"><h2>علاماتك وملاحظات القراءة</h2><div class="card-body" id="readerSavedItems">${renderReaderSavedItems()}</div></section></div>`}
function renderReaderSavedItems(){const marks=readStore('qayyum-reader-bookmarks'),notes=readStore('qayyum-reader-notes'),cloud=window.readerCloudBookmarks||[],cloudNotes=window.readerCloudNotes||[];return [...cloud.map(x=>({id:x.id,action:'reader-cloud-bookmark-delete',page:x.page_label||'',note:x.note||x.title||'علامة محفوظة في حسابك',at:new Date(x.created_at).getTime(),type:'علامة · الحساب'})),...cloudNotes.map(x=>({id:x.id,action:'reader-cloud-note-delete',page:x.locator||'',note:x.body||x.title||'ملاحظة محفوظة في الحساب',at:new Date(x.created_at).getTime(),type:'ملاحظة · الحساب'})),...marks.map(x=>({...x,type:'علامة'})),...notes.map(x=>({...x,type:'ملاحظة'}))].sort((a,b)=>b.at-a.at).slice(0,60).map(x=>`<article class="notice-strip"><b>${x.type} · ${escapeHtml(String(x.page||''))}</b><p>${escapeHtml(x.note||'موضع قراءة محفوظ')}</p><small>${new Date(x.at).toLocaleString('ar')}</small>${x.action?`<button class="btn secondary" type="button" data-action="${x.action}" data-id="${escapeHtml(String(x.id))}">حذف من الحساب</button>`:''}</article>`).join('')||'<div class="empty-state">لا توجد علامات أو ملاحظات بعد.</div>'}
async function loadReaderCloudBookmarks(){if(!API_BASE||!apiToken()){window.readerCloudBookmarks=[];window.readerCloudNotes=[];return}try{const [marks,notes]=await Promise.all([apiRequest('/api/reader/bookmarks'),apiRequest('/api/research/notes')]);window.readerCloudBookmarks=marks.items||[];window.readerCloudNotes=(notes.items||[]).filter(x=>String(x.locator||'').startsWith('قارئ القيّوم · صفحة '));const box=$('#readerSavedItems');if(box)box.innerHTML=renderReaderSavedItems()}catch(err){window.readerCloudBookmarks=[];window.readerCloudNotes=[];toast(`تعذر تحميل محفوظات الحساب: ${err.message}`)}}
async function loadReaderLibrary(name,buffer){const box=$('#readerContent'),status=$('#readerStatus');if(!box)return;const ext=String(name).split('.').pop().toLowerCase();if(!['pdf','epub'].includes(ext)){status.textContent='صيغة غير مدعومة؛ المتاح PDF وEPUB.';return}box.innerHTML='<div class="empty-state">جارٍ تجهيز صفحات الكتاب…</div>';window.readerBytes=buffer;window.readerType=ext;window.readerTitle=String(name);window.readerScale=1;window.readerPageNo=1;window.readerDoc=null;window.readerEpub=null;status.textContent=`${name} · قارئ مكتبة القيّوم`;try{if(ext==='pdf'){await loadReaderScript('https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js');if(!window.pdfjsLib)throw new Error('تعذر تحميل محرك PDF');window.pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';window.readerDoc=await window.pdfjsLib.getDocument({data:new Uint8Array(buffer)}).promise;box.innerHTML='<div class="reader-pdf-stage"><canvas id="readerPdfPage"></canvas></div>';await renderPdfPage(1);status.textContent=`${name} · ${window.readerDoc.numPages} صفحة · داخل مكتبة القيّوم`}else{await loadReaderScript('https://cdn.jsdelivr.net/npm/epubjs/dist/epub.min.js');if(!window.ePub)throw new Error('تعذر تحميل محرك EPUB');box.innerHTML='<div id="epubReader" class="reader-epub-stage"></div>';window.readerEpub=window.ePub(buffer);window.readerEpub.renderTo('epubReader',{width:'100%',height:'75vh',flow:'paginated'});await window.readerEpub.display();status.textContent=`${name} · قراءة EPUB داخل مكتبة القيّوم`}}catch(err){box.innerHTML=`<div class="empty-state">تعذر عرض الكتاب: ${escapeHtml(err.message)}. تحقق من سلامة الملف واتصال الإنترنت.</div>`;status.textContent='تعذر فتح النسخة.'}}
function loadReaderScript(src){return new Promise((resolve,reject)=>{const existing=[...document.scripts].find(x=>x.src===src);if(existing){if(src.includes('pdf.min')&&window.pdfjsLib||src.includes('epub.min')&&window.ePub)return resolve();existing.addEventListener('load',resolve,{once:true});existing.addEventListener('error',reject,{once:true});return}const script=document.createElement('script');script.src=src;script.onload=resolve;script.onerror=()=>reject(new Error('فشل تحميل محرك القراءة'));document.head.append(script)})}
async function renderPdfPage(pageNo){if(!window.readerDoc)return;const page=await window.readerDoc.getPage(Math.max(1,Math.min(window.readerDoc.numPages,pageNo)));window.readerPageNo=pageNo;const canvas=$('#readerPdfPage'),ctx=canvas.getContext('2d'),viewport=page.getViewport({scale:window.readerScale||1.2});canvas.width=viewport.width;canvas.height=viewport.height;canvas.style.width='100%';canvas.style.maxWidth='100%';await page.render({canvasContext:ctx,viewport}).promise;const input=$('#readerPage');if(input)input.value=pageNo}
async function openLocalReader(file){if(!file)return;const ext=file.name.split('.').pop().toLowerCase();if(!['pdf','epub'].includes(ext)){toast('نوع الملف غير مدعوم.');return}const buffer=await file.arrayBuffer();window.readerLocalFile=file;await loadReaderLibrary(file.name,buffer);try{localStorage.setItem('qayyum-last-reader-file',file.name)}catch{}}
async function openLibraryReaderUrl(raw){const status=$('#readerStatus');try{const u=new URL(raw,location.href),allowed=u.origin===location.origin||(API_BASE&&u.origin===new URL(API_BASE).origin);if(!allowed)throw new Error('يجب أن تكون النسخة مستضافة على موقع القيّوم أو خادمه، وليس على موقع خارجي.');status.textContent='جارٍ جلب نسخة مكتبة القيّوم…';const headers={};if(API_BASE&&u.origin===new URL(API_BASE).origin&&apiToken())headers.Authorization=`Bearer ${apiToken()}`;const response=await fetch(u.href,{headers,credentials:'same-origin'});if(!response.ok)throw new Error(`تعذر جلب الملف (${response.status})`);const blob=await response.blob();await loadReaderLibrary(u.pathname.split('/').pop()||'book.pdf',await blob.arrayBuffer())}catch(err){status.textContent=err.message;toast(err.message)}}

function renderPersonal(){return `<div class="page-shell profile-page"><section class="paper-card"><div class="profile-heading"><div><h2>الملف الشخصي</h2><p class="muted">غيّر اسمك الظاهر واسم المستخدم وصورتك ومعلومات حسابك</p></div><span class="chip">إعدادات الحساب</span></div><div class="card-body"><div id="profileStatus" class="notice-strip">جارٍ تحميل بيانات حسابك…</div><div class="profile-layout"><div class="profile-avatar-panel"><img id="profileAvatarPreview" alt="الصورة الشخصية" hidden><div id="profileAvatarFallback" class="profile-avatar-fallback">♙</div><form id="profileAvatarForm"><label class="btn secondary profile-file-label" for="profileAvatarFile">اختيار صورة</label><input id="profileAvatarFile" type="file" accept="image/png,image/jpeg,image/webp" hidden><button class="btn" type="submit">حفظ الصورة</button><button class="btn ghost" type="button" data-action="profile-avatar-remove">حذف الصورة</button></form><small class="muted">PNG أو JPG أو WEBP · حتى 5 ميغابايت</small><div class="profile-cover-editor"><b>صورة الغلاف</b><img id="profileCoverPreview" alt="غلاف الملف الشخصي" hidden><div id="profileCoverFallback" class="profile-cover-fallback">غلاف حسابك</div><form id="profileCoverForm"><label class="btn secondary profile-file-label" for="profileCoverFile">اختيار غلاف</label><input id="profileCoverFile" type="file" accept="image/png,image/jpeg,image/webp" hidden><button class="btn" type="submit">حفظ الغلاف</button><button class="btn ghost" type="button" data-action="profile-cover-remove">حذف الغلاف</button></form></div></div><form id="profileForm" class="profile-fields"><div class="field"><label for="profileDisplayName">الاسم الظاهر</label><input id="profileDisplayName" minlength="2" maxlength="160" required placeholder="الاسم الذي يظهر للآخرين"></div><div class="field"><label for="profileUsername">اسم المستخدم</label><input id="profileUsername" minlength="3" maxlength="32" pattern="[A-Za-z0-9_]+" placeholder="username"><small class="field-hint">أحرف إنجليزية وأرقام وشرطة سفلية فقط</small></div><div class="field"><label for="profileBio">نبذة تعريفية</label><textarea id="profileBio" maxlength="2000" rows="4" placeholder="اكتب نبذة مختصرة عنك"></textarea></div><div class="form-row"><div class="field"><label for="profileLanguage">اللغة المفضلة</label><select id="profileLanguage"><option value="ar">العربية</option><option value="fa">الفارسية</option><option value="en">English</option><option value="ur">اردو</option><option value="tr">Türkçe</option></select></div><div class="field"><label for="profileTimezone">المنطقة الزمنية</label><input id="profileTimezone" maxlength="64" placeholder="مثال: Asia/Baghdad"></div></div><button class="btn auth-submit" type="submit">حفظ التعديلات</button></form></div></div></section><section class="paper-card"><h2>أمان الحساب</h2><div class="card-body"><form id="profilePasswordForm"><div class="form-row"><div class="field"><label for="profileCurrentPassword">كلمة المرور الحالية</label><input id="profileCurrentPassword" type="password" autocomplete="current-password" required></div><div class="field"><label for="profileNewPassword">كلمة المرور الجديدة</label><input id="profileNewPassword" type="password" minlength="12" maxlength="72" autocomplete="new-password" required></div><div class="field"><label for="profileConfirmPassword">تأكيد كلمة المرور الجديدة</label><input id="profileConfirmPassword" type="password" minlength="12" maxlength="72" autocomplete="new-password" required></div></div><button class="btn secondary" type="submit">تغيير كلمة المرور</button></form><p class="muted">متاح للحسابات التي تستخدم البريد وكلمة المرور.</p></div></section><div class="grid-3"><div class="tool-tile"><b>📚 رفوفي</b><p>كتبك المحفوظة ومجموعات القراءة الخاصة.</p></div><div class="tool-tile"><b>🕘 سجل القراءة</b><p>آخر موضع قراءة ونسبة التقدم.</p></div><div class="tool-tile"><b>🔖 العلامات والاقتباسات</b><p>النصوص المحفوظة والحواشي الشخصية.</p></div></div><section class="paper-card"><h2>مكتبتي الشخصية</h2><div class="card-body"><div id="personalLibraryList" class="empty-state">سيظهر هنا سجل القراءة والكتب المحفوظة بعد تحميل بيانات حسابك.</div></div></section></div>`}
function renderNotifications(){const items=[['calendar','مناسبة إسلامية','تذكير بالمناسبات حسب التقويم الذي تختاره'],['book','كتاب جديد','تنبيه عند إضافة كتاب موثق'],['research','البحوث','الردود والمراجعات على مشاريعك'],['community','المجموعات والقنوات','التحديثات والأنشطة المعتمدة'],['security','الأمان','الدخول من جهاز جديد والتنبيهات الأمنية'],['admin','الإدارة','البلاغات والقرارات والطلبات الإدارية']];return `<div class="page-shell"><div class="notice-strip">تظهر هنا إشعارات الحساب الفعلية. إشعارات المتصفح والهاتف تحتاج إعداد خدمة إرسال مستقلة وموافقتك الصريحة.</div><section class="paper-card"><h2>قنوات الإشعار</h2><div class="card-body"><div class="settings-list">${items.map(x=>`<div class="settings-item"><label><span><b>${x[1]}</b><br><small>${x[2]}</small></span><input type="checkbox" class="notification-pref" data-kind="${x[0]}" checked></label></div>`).join('')}</div><button class="btn" data-action="save-notification-preferences">حفظ تفضيلات الإشعارات</button></div></section><section class="paper-card"><div class="toolbar" style="justify-content:space-between"><h2>سجل الإشعارات</h2><button class="btn secondary" data-action="notifications-read-all">تحديد الكل كمقروء</button></div><div class="card-body"><div id="notificationsList" class="empty-state">سجّل الدخول لعرض إشعارات حسابك.</div></div></section></div>`}

function renderAdminDashboard(){return `<div class="page-shell"><div class="notice-strip">هذه مساحة الإدارة المفعّلة للحسابات التي منحها المالك صلاحية الإدارة. لا تتضمن مركز المالك أو إدارة الحسابات والصلاحيات الحساسة.</div><section class="paper-card"><h2>صلاحيات حسابك</h2><div class="card-body"><p>تُحدَّث صلاحياتك من حساب المالك، ويُتحقق منها على الخادم عند كل طلب. إذا سُحبت صلاحية الإدارة أو أُوقف الحساب ينتهي الوصول الإداري مباشرة.</p><div class="toolbar"><button class="btn secondary" data-action="admin-calendar-load">عرض المناسبات المرسلة للمراجعة</button><button class="btn" data-action="admin-workspace-load">المشاريع والمهام والاجتماعات</button><button class="btn secondary" data-action="admin-moderation-load">البلاغات والشكاوى والاستئناف</button><button class="btn secondary" data-action="admin-files-load">مراجعة الملفات والكتب المرفوعة</button></div><div id="adminWorkspacePanel"></div><div id="adminCalendarQueue" class="empty-state">اضغط لعرض قائمة المناسبات المعلقة، إن كانت ضمن صلاحياتك.</div><div id="adminModerationPanel"></div><div id="adminFileQueuePanel"></div></div></section></div>`}

async function loadOwnerDashboardStats(){const ids={books:'ownerStatBooks',members:'ownerStatMembers',spaces:'ownerStatSpaces',pending_reviews:'ownerStatReviews'};try{const d=await apiRequest('/api/admin/dashboard/stats');for(const [key,id] of Object.entries(ids)){const node=document.getElementById(id);if(node){const value=node.matches('strong')?node:node.querySelector('strong');const desc=node.matches('strong')?node.parentElement.querySelector('em,small'):node.querySelector('small');if(value)value.textContent=Number(d[key]??0).toLocaleString('ar');if(desc)desc.textContent='بيانات مباشرة من قاعدة البيانات'}}}catch(err){for(const id of Object.values(ids)){const node=document.getElementById(id);if(node){const value=node.matches('strong')?node:node.querySelector('strong');const desc=node.matches('strong')?node.parentElement.querySelector('em,small'):node.querySelector('small');if(value)value.textContent='—';if(desc)desc.textContent='تعذر تحميل الإحصائية'}}toast('تعذر تحميل إحصائيات مركز المالك: '+err.message)}}
async function loadOwnerBackups(){const host=$('#ownerBackupsPanel');if(!host)return;host.textContent='جارٍ تحميل السياسات والسجل…';try{const d=await apiRequest('/api/admin/backups');host.innerHTML='<h4>السياسات</h4>'+(d.policies||[]).map(p=>'<article class="notice-strip"><b>'+escapeHtml(p.policy_name)+'</b><div class="form-row"><label>التفعيل <input type="checkbox" id="backupEnabled-'+p.id+'" '+(p.enabled?'checked':'')+'></label><label>الدورية <select id="backupCadence-'+p.id+'"><option value="daily" '+(p.cadence==='daily'?'selected':'')+'>يومي</option><option value="weekly" '+(p.cadence==='weekly'?'selected':'')+'>أسبوعي</option><option value="monthly" '+(p.cadence==='monthly'?'selected':'')+'>شهري</option><option value="manual" '+(p.cadence==='manual'?'selected':'')+'>يدوي</option></select></label><label>عدد النسخ المحتفظ بها <input type="number" min="1" max="365" id="backupRetention-'+p.id+'" value="'+p.retention_count+'"></label></div><p>التشفير مطلوب: '+(p.encryption_required?'نعم':'لا')+'</p><button class="btn secondary" data-action="backup-policy-save" data-id="'+p.id+'">حفظ السياسة</button></article>').join('')+'<h4>سجل النسخ</h4>'+((d.runs||[]).map(r=>'<article class="notice-strip"><b>'+escapeHtml(r.status)+'</b><p>'+new Date(r.started_at).toLocaleString('ar')+' · '+(r.byte_size?Number(r.byte_size).toLocaleString('ar')+' بايت':'الحجم غير مسجل')+' · '+(r.encrypted?'مشفّر':'غير مشفّر')+'</p><small>'+escapeHtml(r.result_note||'لا توجد ملاحظات')+'</small></article>').join('')||'<div class="empty-state">لا توجد عمليات نسخ مسجلة.</div>')}catch(err){host.textContent='تعذر تحميل النسخ الاحتياطية: '+err.message}}
async function loadOwnerAuditLogs(){const host=$('#adminManagementPanel');if(!host)return;host.innerHTML='<section class="paper-card"><h2>سجل العمليات والأمان</h2><div class="card-body" id="ownerAuditLogList">جارٍ تحميل السجل…</div></section>';try{const d=await apiRequest('/api/admin/audit-logs?limit=100');const list=$('#ownerAuditLogList');if(list)list.innerHTML=(d.items||[]).map(x=>'<article class="notice-strip"><b>'+escapeHtml(x.action_code)+'</b><p>'+escapeHtml(x.actor_name)+' · '+escapeHtml(x.target_kind||'')+' · '+escapeHtml(x.target_id||'')+'</p><small>'+new Date(x.created_at).toLocaleString('ar')+'</small><details><summary>تفاصيل العملية</summary><pre>'+escapeHtml(JSON.stringify(x.details,null,2))+'</pre></details></article>').join('')||'<div class="empty-state">لا توجد عمليات مسجلة بعد.</div>'}catch(err){const list=$('#ownerAuditLogList');if(list)list.textContent='تعذر تحميل السجل: '+err.message}}
