async function loadCommunityOwnerQueue(){const host=$('#communityOwnerQueue');if(!host)return;try{const d=await apiRequest('/api/admin/community/spaces');host.innerHTML=d.items.length?d.items.map(x=>{const state={pending_owner_review:'بانتظار الموافقة',active:'نشطة',paused:'متوقفة',rejected:'مرفوضة',archived:'مؤرشفة'}[x.status]||x.status;const actions=x.status==='pending_owner_review'?'<button class="btn" data-action="community-space-decision" data-id="'+x.id+'" data-status="active">اعتماد</button><button class="btn secondary" data-action="community-space-decision" data-id="'+x.id+'" data-status="rejected">رفض</button>':x.status==='active'?'<button class="btn secondary" data-action="community-space-decision" data-id="'+x.id+'" data-status="paused">إيقاف مؤقت</button><button class="btn ghost" data-action="community-space-decision" data-id="'+x.id+'" data-status="archived">أرشفة</button>':x.status==='paused'?'<button class="btn" data-action="community-space-decision" data-id="'+x.id+'" data-status="active">إعادة تفعيل</button><button class="btn ghost" data-action="community-space-decision" data-id="'+x.id+'" data-status="archived">أرشفة</button>':'<button class="btn" data-action="community-space-decision" data-id="'+x.id+'" data-status="active">إعادة تفعيل</button>';return '<article class="notice-strip"><b>'+escapeHtml(x.name)+' · '+(x.space_kind==='group'?'مجموعة':'قناة')+'</b><p>'+escapeHtml(x.creator)+' · '+escapeHtml(x.description||'')+'</p><small>الحالة: '+escapeHtml(state)+' · الخصوصية: '+escapeHtml(x.privacy)+'</small><div class="toolbar">'+actions+(x.status==='active'?'<button class="btn ghost" data-action="community-members" data-id="'+x.id+'">الأعضاء</button><button class="btn ghost" data-action="community-pending-posts" data-id="'+x.id+'">مراجعة المنشورات</button>':'')+'</div><div id="communityMembers-'+x.id+'"></div><div id="communityPending-'+x.id+'"></div></article>'}).join(''):'<div class="empty-state">لا توجد مجموعات أو قنوات حتى الآن.</div>'}catch(err){host.textContent='تعذر تحميل المساحات: '+err.message}}
