function renderPage(key){if(['admin','dashboard','staff'].includes(key)&&!sessionChecked){home.hidden=false;page.hidden=true;return}if(key==='dashboard'&&currentSession?.accountType!=='owner'){toast('مركز المالك مخصص للمالك فقط.');location.hash=currentSession?.isAdmin?'#admin':'#home';return}if(key==='admin'&&!currentSession?.isAdmin){toast('هذا القسم متاح للحسابات الإدارية المفعّلة فقط.');location.hash='#home';return}if(key==='staff'&&currentSession?.accountType!=='owner'){toast('إدارة الأقسام والموظفين متاحة للمالك فقط حالياً.');location.hash=currentSession?.isAdmin?'#admin':'#home';return}const renderers={assistant:renderAssistant,reader:renderReader,personal:renderPersonal,library:renderLibrary,authors:renderAuthors,audio:renderAudio,tests:renderTests,articles:renderArticles,register:renderRegister,history:renderLibrary,fiqh:renderLibrary,ahlulbayt:renderLibrary,aqaed:renderLibrary,quran:renderLibrary,ethics:renderLibrary,language:renderLibrary,research:renderResearch,hadith:renderHadith,calendar:renderCalendar,study:renderStudy,groups:renderGroups,notifications:renderNotifications,admin:renderAdminDashboard,dashboard:renderDashboard,login:renderLogin,settings:renderSettings,about:()=>`<div class="page-shell"><section class="paper-card"><h2>رسالة المكتبة</h2><div class="card-body"><p>مكتبة القيّوم مشروع علمي لفهرسة مصادر المعرفة الإسلامية، وإتاحة البحث والقراءة والتحقيق، مع احترام تعدد المدارس والمناهج واللغات وحقوق النشر.</p><p>تعتمد المكتبة التوثيق الببليوغرافي، وفصل النص المنقول عن التقييم والتحليل، وعدم نسبة كتاب أو رواية إلى مدرسة أو مؤلف دون دليل.</p></div></section></div>`,contact:renderContact,rijal:renderRijal,comparative:()=>renderLibrary('دراسات مقارنة'),manuscripts:renderManuscripts,ocr:renderPlannedModule,translations:renderTranslations,sources:renderSources,publishers:renderPublishers,digital:renderReader,logic:()=>renderLibrary('المنطق'),quality:renderPlannedModule,staff:renderDashboard,projects:renderResearch,usul:()=>renderLibrary('أصول الفقه'),economy:()=>renderLibrary('الاقتصاد'),society:()=>renderLibrary('العلوم الاجتماعية'),education:()=>renderLibrary('التربية والتعليم'),geography:()=>renderLibrary('الجغرافيا'),law:()=>renderLibrary('القانون'),natural:()=>renderLibrary('العلوم الطبيعية'),prayers:()=>renderLibrary('الأدعية والزيارات')};
 if(key==='home'||!key){home.hidden=false;page.hidden=true;return}
 home.hidden=true;page.hidden=false;page.innerHTML=pageHeader(key)+(renderers[key]?renderers[key]():`<div class="page-shell"><div class="empty-state">هذا القسم سيُربط ضمن قاعدة بيانات المكتبة.</div></div>`);window.scrollTo({top:0,behavior:'smooth'});loadLocalNotes();if(key==='research')loadResearchProjects();else loadLocalProjects();if(key==='study'){loadStudyNotes()}if(key==='reader'){loadReaderCloudBookmarks()}if(key==='personal'){loadMyProfile()}if(key==='contact'){loadMySupportTickets()}if(key==='calendar'){loadCalendarEvents();loadPlatformPreferences()}if(key==='notifications'){loadNotifications();loadPlatformPreferences()}if(key==='groups'){loadCommunitySpaces()}if(key==='dashboard'){loadOwnerDashboardStats()}if(key==='settings'){loadPlatformPreferences()}}
